import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { String line = br.readLine(); while (line != null && line.isEmpty()) line = br.readLine(); int n = Integer.parseInt(line.trim()); Map<String, Long> map = new HashMap<>(); for (int i = 0; i < 3 * n; i++) { StringTokenizer st2 = new StringTokenizer(br.readLine()); String code = st2.nextToken(); long count = Long.parseLong(st2.nextToken()); map.put(code, map.getOrDefault(code, 0L) + count); } long[] results = new long[map.size()]; int idx = 0; for (long val : map.values()) { results[idx++] = val; } Arrays.sort(results); for (int i = 0; i < results.length; i++) { out.print(results[i] + (i == results.length - 1 ? "" : " ")); } out.println(); } out.flush(); out.close(); } }